head.b:template-skin:

body#layout { font-family: sans-serif; background: #f8f9fa; }
body#layout .b-section { border: 2px dashed #0d6efd; padding: 15px; margin-bottom: 25px; background: #ffffff; border-radius: 8px; }
body#layout .b-section h4 { color: #212529; font-weight: bold; margin-bottom: 15px; font-size: 14px; text-transform: uppercase; background: #e9ecef; padding: 8px; border-radius: 4px; }
body#layout #top-bar, body#layout #hero-text, body#layout #hero-media, 
body#layout #saas-cards, body#layout #pricing-cards, body#layout #testimonials, 
body#layout #pre-footer { display: block !important; }

head.b:skin:

    /*
    <Group description="🎨 Cores do Tema (Nexus SaaS)" selector=":root">
      <Variable name="cor.primaria" description="Cor Principal (Azul Destaque)" type="color" default="#0d6efd" value="#0d6efd"/>
      <Variable name="cor.escura" description="Cor Escura (Textos e Títulos)" type="color" default="#1e293b" value="#1e293b"/>
      <Variable name="cor.clara" description="Cor de Fundo Secundário" type="color" default="#f8fafc" value="#f8fafc"/>
      <Variable name="cor.cinza" description="Cor dos Textos Menores" type="color" default="#64748b" value="#64748b"/>
    </Group>
    */

    :root {
      --nexus-primary: $(cor.primaria);
      --nexus-dark: $(cor.escura);
      --nexus-light: $(cor.clara);
      --nexus-gray: $(cor.cinza);
    }

    body { font-family: 'Space Grotesk', sans-serif; background-color: var(--nexus-light); color: var(--nexus-dark); overflow-x: hidden; }

    /* Utilitários Gerais */
    a { text-decoration: none; transition: all 0.3s ease; }
    .fade-in-up { opacity: 0; transform: translateY(30px); transition: opacity 0.8s ease-out, transform 0.8s ease-out; }
    .fade-in-up.is-visible { opacity: 1; transform: translateY(0); }

    /* AVISO TOPO */
    .top-bar-wrapper .widget { background: var(--nexus-primary); color: #fff; text-align: center; padding: 8px 15px; font-size: 0.9rem; font-weight: 500; }
    .top-bar-wrapper .widget h2 { display: none; }

    /* NAVBAR */
    .navbar-nexus { background: rgba(255, 255, 255, 0.95); backdrop-filter: blur(10px); border-bottom: 1px solid #e2e8f0; padding: 1rem 0; }
    .navbar-nexus .Header h1 { margin: 0; font-size: 1.5rem; font-weight: 700; color: var(--nexus-dark); }
    .navbar-nexus .Header img { max-height: 40px; }

    /* HERO SECTION */
    .hero-section { padding: 140px 0 80px 0; background: #ffffff; border-bottom: 1px solid #e2e8f0; }
    .hero-text-area { display: flex; flex-direction: column; justify-content: center; height: 100%; }
    .hero-text-area .widget h2.title { font-size: 3.5rem; font-weight: 700; letter-spacing: -1px; margin-bottom: 1.5rem; line-height: 1.2; color: var(--nexus-dark); }
    .hero-text-area .widget .widget-content { font-size: 1.25rem; color: var(--nexus-gray); line-height: 1.6; margin-bottom: 2rem; }
    .hero-media-area .widget img { width: 100%; max-width: 600px; height: auto; border-radius: 20px; box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1); }
    .hero-media-area .widget h2.title { display: none; }

    @media (max-width: 768px) {
      .hero-text-area .widget h2.title { font-size: 2.5rem; text-align: center; }
      .hero-text-area .widget .widget-content { text-align: center; }
      .hero-text-area .btn-hero-wrapper { text-align: center; }
    }

    /* SISTEMA GERAL DE CARDS (GRID) */
    .cards-wrapper { padding: 80px 0; }
    .cards-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 30px; }

    /* CARDS DE FUNCIONALIDADES */
    #saas-cards .widget {
      background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; padding: 40px 30px;
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05); transition: all 0.4s ease; height: 100%; display: flex; flex-direction: column;
    }
    #saas-cards .widget:hover { transform: translateY(-10px); box-shadow: 0 20px 25px -5px rgba(13, 110, 253, 0.1); border-color: var(--nexus-primary); }
    #saas-cards .widget h2.title { font-size: 1.5rem; font-weight: 700; color: var(--nexus-dark); margin-bottom: 15px; border-bottom: none; }
    #saas-cards .widget h2.title::before { content: "\F287"; font-family: "bootstrap-icons"; display: block; font-size: 2.5rem; color: var(--nexus-primary); margin-bottom: 15px; }
    #saas-cards .widget .widget-content { color: var(--nexus-gray); font-size: 1rem; line-height: 1.7; flex-grow: 1; }

    /* CARDS DE PREÇOS (PRICING) */
    .pricing-wrapper { background: var(--nexus-light); padding: 80px 0; }
    #pricing-cards .widget {
      background: #ffffff; border: 2px solid #e2e8f0; border-radius: 20px; padding: 50px 40px; text-align: center;
      transition: all 0.4s ease; height: 100%; display: flex; flex-direction: column; align-items: center;
    }
    #pricing-cards .widget:hover { border-color: var(--nexus-primary); box-shadow: 0 20px 40px rgba(13, 110, 253, 0.08); transform: scale(1.02); }
    #pricing-cards .widget h2.title { font-size: 1.5rem; font-weight: 700; color: var(--nexus-dark); margin-bottom: 10px; text-transform: uppercase; letter-spacing: 1px; border: none; }
    #pricing-cards .widget .widget-content { color: var(--nexus-gray); font-size: 1.1rem; line-height: 1.6; flex-grow: 1; display: flex; flex-direction: column; }
   #pricing-cards .widget .widget-content .btn { margin-top: auto !important; }
    #pricing-cards .widget .widget-content p:first-of-type::before { content: "R$ "; font-size: 1.5rem; vertical-align: super; color: var(--nexus-gray); }
/* Aumenta o número do preço */
    #pricing-cards .widget .widget-content p:first-of-type { 
      font-size: 3.5rem; 
      font-weight: 800; 
      color: var(--nexus-dark); 
      margin-bottom: 5px;
      line-height: 1;
    }

    /* Ajusta o R$ para não ficar desproporcional */
    #pricing-cards .widget .widget-content p:first-of-type::before { 
      font-size: 1.2rem; 
    }

    /* CARDS DE DEPOIMENTOS */
    #testimonials .widget { background: #ffffff; border-radius: 16px; padding: 30px; border: 1px solid #e2e8f0; font-style: italic; color: var(--nexus-gray); }
    #testimonials .widget h2.title { font-size: 1.1rem; font-weight: 700; color: var(--nexus-dark); margin-top: 20px; font-style: normal; border: none; }
    #testimonials .widget h2.title::before { content: "\F6B0"; font-family: "bootstrap-icons"; display: block; font-size: 2rem; color: #ffc107; margin-bottom: 10px; }

    /* BLOG / ARTIGOS */
    .blog-section { padding: 80px 0; background: #ffffff; border-top: 1px solid #e2e8f0; }
    .post-card { background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; height: 100%; transition: all 0.3s; }
    .post-card:hover { box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1); }
    .post-card-img { width: 100%; height: 220px; object-fit: cover; background: #f1f5f9; }
    .post-card-body { padding: 25px; }
    .post-title a { color: var(--nexus-dark); font-weight: 700; font-size: 1.25rem; }
    .post-title a:hover { color: var(--nexus-primary); }
    .post-snippet { color: var(--nexus-gray); margin-top: 10px; font-size: 0.95rem; }

    /* FOOTER */
    .footer-nexus { background: var(--nexus-dark); color: #94a3b8; padding: 60px 0 30px 0; }
    .footer-nexus .widget h2.title { color: #ffffff; font-weight: 700; margin-bottom: 20px; border: none; }

body.script:
//
  document.addEventListener('DOMContentLoaded', () => {
    const observer = new IntersectionObserver((entries, obs) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          obs.unobserve(entry.target);
        }
      });
    }, { root: null, rootMargin: '0px', threshold: 0.1 });

    document.querySelectorAll('.fade-in-up').forEach((el, index) => {
      el.style.transitionDelay = `${(index % 3) * 0.15}s`;
      observer.observe(el);
    });
  });
//
